INSERT INTO `chat_messages` (`id`, `user_id`, `message_type`, `content`, `created_at`, `quick_entry_data`, `is_quick_entry_confirmed`) VALUES ('4110b868-ff64-4cf9-9990-5bd5d26e077c', 'd7d024ec-60e7-461d-a695-e7286fd32bdd', 'ai', '我是TATA～owner想我了吗？我可以陪owner聊天聊好久好久呢！\n\nTATA最会听owner说话啦，不开心的事情都可以告诉我哦～\n\n我知道好多健康小知识，可以告诉owner怎么吃好睡好呢！\n\nowner想聊什么都可以，TATA都会认真听的！\n\n你可以自由定义你喜欢的搭子风格哦，点击[我的图像]即可开始定制！', '2025-11-20 11:21:16', NULL, 0);
