INSERT INTO `chat_messages` (`id`, `user_id`, `message_type`, `content`, `created_at`, `quick_entry_data`, `is_quick_entry_confirmed`) VALUES ('21d883d2-8233-45c6-ac0d-241d976c4418', '33221914-d34b-4e39-9a96-965dc1da597d', 'ai', 'owner，今天感觉怎么样？数据告诉我你昨晚睡得不错，但水喝得有点少。', '2025-12-09 12:55:10', NULL, 0);
