INSERT INTO `chat_messages` (`id`, `user_id`, `message_type`, `content`, `created_at`, `quick_entry_data`, `is_quick_entry_confirmed`) VALUES ('a5df6064-9031-456f-915d-73cd3e9e7f7b', '33221914-d34b-4e39-9a96-965dc1da597d', 'quickEntry', '', '2025-12-09 12:55:29', '{"date":"2025-12-09T04:55:28.473Z","unit":"ml","notes":"","value":500,"dailyCount":5,"dataSource":"ai","metricType":"water","syncedToRecords":false,"isManuallyEdited":false,"isSavedToDatabase":false}', 0);
INSERT INTO `chat_messages` (`id`, `user_id`, `message_type`, `content`, `created_at`, `quick_entry_data`, `is_quick_entry_confirmed`) VALUES ('f54241d2-a7ff-445e-ad06-49941eed8be6', '33221914-d34b-4e39-9a96-965dc1da597d', 'ai', '（点头）很好，owner。今天已经喝了1250ml，继续保持。记得均匀分配，别等到渴了才猛灌。', '2025-12-09 12:55:34', NULL, 0);
INSERT INTO `chat_messages` (`id`, `user_id`, `message_type`, `content`, `created_at`, `quick_entry_data`, `is_quick_entry_confirmed`) VALUES ('4d67715c-57af-4b58-a8ab-400a2bc78f8e', '2e1ee615-ef0f-4a67-8137-a7252afa2378', 'quickEntry', '', '2025-12-10 16:13:22', '{"date":"2025-12-10T08:12:58.694Z","unit":"碗","value":2,"calories":232,"foodName":"米饭","mealType":"午餐","quantity":2,"dailyCount":1,"dataSource":"ai","metricType":"food","syncedToRecords":true,"isManuallyEdited":true,"isSavedToDatabase":true}', 1);
