INSERT INTO `chat_messages` (`id`, `user_id`, `message_type`, `content`, `created_at`, `quick_entry_data`, `is_quick_entry_confirmed`) VALUES ('581a1435-d04b-46f8-8123-013b6d736ba6', '2e1ee615-ef0f-4a67-8137-a7252afa2378', 'ai', 'owner，我是TATA，你的健康教练，不需要吃东西哦～不过看到你今天已经记录了928千卡的饮食，看起来吃得挺丰富的呢！如果你需要调整饮食计划或者想分享吃了什么，我随时在这里帮你分析哦～ 😊', '2025-12-10 16:49:11', NULL, 0);
INSERT INTO `custom_reports` (`id`, `user_id`, `report_type`, `title`, `generation_date`, `status`, `report_data`, `created_at`, `updated_at`) VALUES ('8ae8ed31-2188-42c8-80a5-0da59b8d1651', '2e1ee615-ef0f-4a67-8137-a7252afa2378', 'ai_analysis', 'AI健康数据解读报告', '2025-11-28 17:38:16', 'active', '{"html":"<!DOCTYPE html>\\n<html lang=\\"zh-CN\\">\\n<head>\\n    <meta charset=\\"UTF-8\\">\\n    <meta name=\\"viewport\\" content=\\"width=device-width, initial-scale=1.0\\">\\n    <title>健康解读报告 - 勇敢的狮子</title>\\n    <script src=\\"https://cdn.tailwindcss.com\\"></script>\\n    <script src=\\"https://cdn.jsdelivr.net/npm/chart.js\\"></script>\\n    <script>\\n        tailwind.config = {\\n            theme: {\\n                extend: {\\n                    colors: {\\n                        primary: ''#f0f9f4''\\n                    }\\n                }\\n            }\\n        }\\n    </script>\\n</head>\\n<body class=\\"bg-primary min-h-screen\\">\\n    <div class=\\"container mx-auto px-4 py-8\\">\\n        <!-- 免责声明 -->\\n        <div class=\\"bg-white rounded-lg shadow-sm p-6 mb-6\\">\\n            <p class=\\"text-sm text-gray-600 mb-2\\">本报告仅供参考，不构成医疗建议</p>\\n            <p class=\\"text-sm text-gray-600\\">生成时间：2025年11月27日</p>\\n        </div>\\n\\n        <!-- 执行摘要 -->\\n        <div class=\\"bg-white rounded-lg shadow-sm p-6 mb-6\\">\\n            <h1 class=\\"text-2xl font-bold text-gray-800 mb-4\\">健康解读报告</h1>\\n            <div class=\\"grid grid-cols-1 md:grid-cols-3 gap-4\\">\\n                <div class=\\"text-center\\">\\n                    <p class=\\"text-3xl font-bold text-green-600\\">74</p>\\n                    <p class=\\"text-gray-600\\">综合健康评分</p>\\n                </div>\\n                <div class=\\"text-center\\">\\n                    <p class=\\"text-3xl font-bold text-green-600\\">70kg</p>\\n                    <p class=\\"text-gray-600\\">当前体重</p>\\n                </div>\\n                <div class=\\"text-center\\">\\n                    <p class=\\"text-3xl font-bold text-green-600\\">65kg</p>\\n                    <p class=\\"text-gray-600\\">目标体重</p>\\n                </div>\\n            </div>\\n        </div>\\n\\n        <!-- 数据概览 -->\\n        <div class=\\"bg-white rounded-lg shadow-sm p-6 mb-6\\">\\n            <h2 class=\\"text-xl font-bold text-gray-800 mb-4\\">数据概览</h2>\\n            <div class=\\"grid grid-cols-1 md:grid-cols-2 gap-6\\">\\n                <div>\\n                    <canvas id=\\"weightChart\\"></canvas>\\n                </div>\\n                <div>\\n                    <canvas id=\\"healthScoreChart\\"></canvas>\\n                </div>\\n                <div>\\n                    <canvas id=\\"waterIntakeChart\\"></canvas>\\n                </div>\\n                <div>\\n                    <canvas id=\\"nutritionChart\\"></canvas>\\n                </div>\\n            </div>\\n        </div>\\n\\n        <!-- 健康评估 -->\\n        <div class=\\"bg-white rounded-lg shadow-sm p-6 mb-6\\">\\n            <h2 class=\\"text-xl font-bold text-gray-800 mb-4\\">健康评估</h2>\\n            <div class=\\"grid grid-cols-1 md:grid-cols-2 gap-6\\">\\n                <div>\\n                    <h3 class=\\"font-semibold text-gray-700 mb-2\\">身体指标</h3>\\n                    <ul class=\\"space-y-2\\">\\n                        <li class=\\"flex justify-between\\">\\n                            <span class=\\"text-gray-600\\">身高</span>\\n                            <span class=\\"font-medium\\">181cm</span>\\n                        </li>\\n                        <li class=\\"flex justify-between\\">\\n                            <span class=\\"text-gray-600\\">体重</span>\\n                            <span class=\\"font-medium\\">70kg</span>\\n                        </li>\\n                        <li class=\\"flex justify-between\\">\\n                            <span class=\\"text-gray-600\\">腰围</span>\\n                            <span class=\\"font-medium\\">43cm</span>\\n                        </li>\\n                        <li class=\\"flex justify-between\\">\\n                            <span class=\\"text-gray-600\\">基础代谢率</span>\\n                            <span class=\\"font-medium\\">1495 kcal</span>\\n                        </li>\\n                    </ul>\\n                </div>\\n                <div>\\n                    <h3 class=\\"font-semibold text-gray-700 mb-2\\">健康评分</h3>\\n                    <ul class=\\"space-y-2\\">\\n                        <li class=\\"flex justify-between\\">\\n                            <span class=\\"text-gray-600\\">饮食评分</span>\\n                            <span class=\\"font-medium text-green-600\\">100</span>\\n                        </li>\\n                        <li class=\\"flex justify-between\\">\\n                            <span class=\\"text-gray-600\\">运动评分</span>\\n                            <span class=\\"font-medium text-yellow-600\\">70</span>\\n                        </li>\\n                        <li class=\\"flex justify-between\\">\\n                            <span class=\\"text-gray-600\\">休息评分</span>\\n                            <span class=\\"font-medium text-red-600\\">50</span>\\n                        </li>\\n                        <li class=\\"flex justify-between\\">\\n                            <span class=\\"text-gray-600\\">心理评分</span>\\n                            <span class=\\"font-medium text-yellow-600\\">60</span>\\n                        </li>\\n                    </ul>\\n                </div>\\n            </div>\\n        </div>\\n\\n        <!-- 关键发现 -->\\n        <div class=\\"bg-white rounded-lg shadow-sm p-6 mb-6\\">\\n            <h2 class=\\"text-xl font-bold text-gray-800 mb-4\\">关键发现</h2>\\n            <div class=\\"space-y-3\\">\\n                <div class=\\"flex items-start\\">\\n                    <div class=\\"w-2 h-2 bg-green-500 rounded-full mt-2 mr-3\\"></div>\\n                    <p class=\\"text-gray-700\\">饮食记录良好，营养摄入均衡</p>\\n                </div>\\n                <div class=\\"flex items-start\\">\\n                    <div class=\\"w-2 h-2 bg-yellow-500 rounded-full mt-2 mr-3\\"></div>\\n                    <p class=\\"text-gray-700\\">作息质量需要重点关注和改善</p>\\n                </div>\\n                <div class=\\"flex items-start\\">\\n                    <div class=\\"w-2 h-2 bg-green-500 rounded-full mt-2 mr-3\\"></div>\\n                    <p class=\\"text-gray-700\\">已开始21天减肥计划，目标明确</p>\\n                </div>\\n                <div class=\\"flex items-start\\">\\n                    <div class=\\"w-2 h-2 bg-yellow-500 rounded-full mt-2 mr-3\\"></div>\\n                    <p class=\\"text-gray-700\\">饮水量需要增加，目前记录较少</p>\\n                </div>\\n            </div>\\n        </div>\\n\\n        <!-- 个性化建议 -->\\n        <div class=\\"bg-white rounded-lg shadow-sm p-6 mb-6\\">\\n            <h2 class=\\"text-xl font-bold text-gray-800 mb-4\\">个性化建议</h2>\\n            <div class=\\"space-y-6\\">\\n                <div class=\\"border-l-4 border-green-500 pl-4\\">\\n                    <h3 class=\\"font-semibold text-gray-700 mb-2\\">改善作息质量</h3>\\n                    <div class=\\"grid grid-cols-1 md:grid-cols-2 gap-4 text-sm\\">\\n                        <div>\\n                            <p class=\\"font-medium text-gray-600\\">触发条件</p>\\n                            <p class=\\"text-gray-700\\">晚上11点后仍感觉精力充沛</p>\\n                        </div>\\n                        <div>\\n                            <p class=\\"font-medium text-gray-600\\">微习惯</p>\\n                            <p class=\\"text-gray-700\\">每晚10:30关闭电子设备</p>\\n                        </div>\\n                        <div>\\n                            <p class=\\"font-medium text-gray-600\\">进阶路径</p>\\n                            <p class=\\"text-gray-700\\">建立固定睡眠时间，睡前阅读15分钟</p>\\n                        </div>\\n                        <div>\\n                            <p class=\\"font-medium text-gray-600\\">预期收益</p>\\n                            <p class=\\"text-gray-700\\">提高日间精力，改善心理状态</p>\\n                        </div>\\n                    </div>\\n                </div>\\n\\n                <div class=\\"border-l-4 border-green-500 pl-4\\">\\n                    <h3 class=\\"font-semibold text-gray-700 mb-2\\">增加饮水量</h3>\\n                    <div class=\\"grid grid-cols-1 md:grid-cols-2 gap-4 text-sm\\">\\n                        <div>\\n                            <p class=\\"font-medium text-gray-600\\">触发条件</p>\\n                            <p class=\\"text-gray-700\\">感觉口渴或嘴唇干燥</p>\\n                        </div>\\n                        <div>\\n                            <p class=\\"font-medium text-gray-600\\">微习惯</p>\\n                            <p class=\\"text-gray-700\\">每餐前喝一杯水</p>\\n                        </div>\\n                        <div>\\n                            <p class=\\"font-medium text-gray-600\\">进阶路径</p>\\n                            <p class=\\"text-gray-700\\">使用1.5L水壶，设定每小时饮水提醒</p>\\n                        </div>\\n                        <div>\\n                            <p class=\\"font-medium text-gray-600\\">预期收益</p>\\n                            <p class=\\"text-gray-700\\">促进新陈代谢，改善皮肤状态</p>\\n                        </div>\\n                    </div>\\n                </div>\\n\\n                <div class=\\"border-l-4 border-green-500 pl-4\\">\\n                    <h3 class=\\"font-semibold text-gray-700 mb-2\\">优化运动计划</h3>\\n                    <div class=\\"grid grid-cols-1 md:grid-cols-2 gap-4 text-sm\\">\\n                        <div>\\n                            <p class=\\"font-medium text-gray-600\\">触发条件</p>\\n                            <p class=\\"text-gray-700\\">久坐超过1小时</p>\\n                        </div>\\n                        <div>\\n                            <p class=\\"font-medium text-gray-600\\">微习惯</p>\\n                            <p class=\\"text-gray-700\\">每小时站立活动5分钟</p>\\n                        </div>\\n                        <div>\\n                            <p class=\\"font-medium text-gray-600\\">进阶路径</p>\\n                            <p class=\\"text-gray-700\\">每周3次力量训练，2次有氧运动</p>\\n                        </div>\\n                        <div>\\n                            <p class=\\"font-medium text-gray-600\\">预期收益</p>\\n                            <p class=\\"text-gray-700\\">增强肌肉线条，提高基础代谢</p>\\n                        </div>\\n                    </div>\\n                </div>\\n\\n                <div class=\\"border-l-4 border-green-500 pl-4\\">\\n                    <h3 class=\\"font-semibold text-gray-700 mb-2\\">心理状态调节</h3>\\n                    <div class=\\"grid grid-cols-1 md:grid-cols-2 gap-4 text-sm\\">\\n                        <div>\\n                            <p class=\\"font-medium text-gray-600\\">触发条件</p>\\n                            <p class=\\"text-gray-700\\">感到压力或焦虑时</p>\\n                        </div>\\n                        <div>\\n                            <p class=\\"font-medium text-gray-600\\">微习惯</p>\\n                            <p class=\\"text-gray-700\\">深呼吸3次，放松肩颈</p>\\n                        </div>\\n                        <div>\\n                            <p class=\\"font-medium text-gray-600\\">进阶路径</p>\\n                            <p class=\\"text-gray-700\\">每天10分钟冥想，记录情绪日记</p>\\n                        </div>\\n                        <div>\\n                            <p class=\\"font-medium text-gray-600\\">预期收益</p>\\n                            <p class=\\"text-gray-700\\">降低压力水平，提升生活质量</p>\\n                        </div>\\n                    </div>\\n                </div>\\n\\n                <div class=\\"border-l-4 border-green-500 pl-4\\">\\n                    <h3 class=\\"font-semibold text-gray-700 mb-2\\">饮食结构调整</h3>\\n                    <div class=\\"grid grid-cols-1 md:grid-cols-2 gap-4 text-sm\\">\\n                        <div>\\n                            <p class=\\"font-medium text-gray-600\\">触发条件</p>\\n                            <p class=\\"text-gray-700\\">准备午餐和晚餐时</p>\\n                        </div>\\n                        <div>\\n                            <p class=\\"font-medium text-gray-600\\">微习惯</p>\\n                            <p class=\\"text-gray-700\\">每餐包含一份蛋白质和两份蔬菜</p>\\n                        </div>\\n                        <div>\\n                            <p class=\\"font-medium text-gray-600\\">进阶路径</p>\\n                            <p class=\\"text-gray-700\\">控制碳水摄入时间，晚餐减少主食</p>\\n                        </div>\\n                        <div>\\n                            <p class=\\"font-medium text-gray-600\\">预期收益</p>\\n                            <p class=\\"text-gray-700\\">促进减重，维持肌肉量</p>\\n                        </div>\\n                    </div>\\n                </div>\\n            </div>\\n        </div>\\n\\n        <!-- 行动计划 -->\\n        <div class=\\"bg-white rounded-lg shadow-sm p-6\\">\\n            <h2 class=\\"text-xl font-bold text-gray-800 mb-4\\">行动计划</h2>\\n            <div class=\\"space-y-4\\">\\n                <div class=\\"flex items-center\\">\\n                    <div class=\\"w-8 h-8 bg-green-500 text-white rounded-full flex items-center justify-center mr-3\\">1</div>\\n                    <div>\\n                        <p class=\\"font-medium text-gray-700\\">第一周：建立基础习惯</p>\\n                        <p class=\\"text-sm text-gray-600\\">固定睡眠时间，增加饮水量至2000ml/天</p>\\n                    </div>\\n                </div>\\n                <div class=\\"flex items-center\\">\\n                    <div class=\\"w-8 h-8 bg-green-500 text-white rounded-full flex items-center justify-center mr-3\\">2</div>\\n                    <div>\\n                        <p class=\\"font-medium text-gray-700\\">第二周：引入运动计划</p>\\n                        <p class=\\"text-sm text-gray-600\\">每周3次30分钟力量训练，开始记录运动数据</p>\\n                    </div>\\n                </div>\\n                <div class=\\"flex items-center\\">\\n                    <div class=\\"w-8 h-8 bg-green-500 text-white rounded-full flex items-center justify-center mr-3\\">3</div>\\n                    <div>\\n                        <p class=\\"font-medium text-gray-700\\">第三周：优化饮食结构</p>\\n                        <p class=\\"text-sm text-gray-600\\">调整晚餐营养比例，控制碳水摄入</p>\\n                    </div>\\n                </div>\\n                <div class=\\"flex items-center\\">\\n                    <div class=\\"w-8 h-8 bg-green-500 text-white rounded-full flex items-center justify-center mr-3\\">4</div>\\n                    <div>\\n                        <p class=\\"font-medium text-gray-700\\">第四周：综合评估调整</p>\\n                        <p class=\\"text-sm text-gray-600\\">评估进展，调整计划，建立长期习惯</p>\\n                    </div>\\n                </div>\\n            </div>\\n        </div>\\n    </div>\\n\\n    <script>\\n        // 体重图表\\n        const weightCtx = document.getElementById(''weightChart'').getContext(''2d'');\\n        new Chart(weightCtx, {\\n            type: ''line'',\\n            data: {\\n                labels: [''初始记录''],\\n                datasets: [{\\n                    label: ''体重 (kg)'',\\n                    data: [70],\\n                    borderColor: ''#10b981'',\\n                    backgroundColor: ''rgba(16, 185, 129, 0.1)'',\\n                    borderWidth: 2,\\n                    fill: true\\n                }]\\n            },\\n            options: {\\n                responsive: true,\\n                plugins: {\\n                    title: {\\n                        display: true,\\n                        text: ''体重趋势''\\n                    }\\n                },\\n                scales: {\\n                    y: {\\n                        beginAtZero: false,\\n                        min: 60\\n                    }\\n                }\\n            }\\n        });\\n\\n        // 健康评分图表\\n        const scoreCtx = document.getElementById(''healthScoreChart'').getContext(''2d'');\\n        new Chart(scoreCtx, {\\n            type: ''radar'',\\n            data: {\\n                labels: [''饮食'', ''运动'', ''休息'', ''心理'', ''锻炼''],\\n                datasets: [{\\n                    label: ''健康评分'',\\n                    data: [100, 70, 50, 60, 88],\\n                    backgroundColor: ''rgba(16, 185, 129, 0.2)'',\\n                    borderColor: ''#10b981'',\\n                    borderWidth: 2\\n                }]\\n            },\\n            options: {\\n                responsive: true,\\n                plugins: {\\n                    title: {\\n                        display: true,\\n                        text: ''健康评分分布''\\n                    }\\n                },\\n                scales: {\\n                    r: {\\n                        beginAtZero: true,\\n                        max: 100\\n                    }\\n                }\\n            }\\n        });\\n\\n        // 饮水量图表\\n        const waterCtx = document.getElementById(''waterIntakeChart'').getContext(''2d'');\\n        new Chart(waterCtx, {\\n            type: ''bar'',\\n            data: {\\n                labels: [''11月24日''],\\n                datasets: [{\\n                    label: ''饮水量 (ml)'',\\n                    data: [750],\\n                    backgroundColor: ''#10b981'',\\n                    borderColor: ''#059669'',\\n                    borderWidth: 1\\n                }]\\n            },\\n            options: {\\n                responsive: true,\\n                plugins: {\\n                    title: {\\n                        display: true,\\n                        text: ''每日饮水量''\\n                    }\\n                },\\n                scales: {\\n                    y: {\\n                        beginAtZero: true,\\n                        max: 2000\\n                    }\\n                }\\n            }\\n        });\\n\\n        // 营养摄入图表\\n        const nutritionCtx = document.getElementById(''nutritionChart'').getContext(''2d'');\\n        new Chart(nutritionCtx, {\\n            type: ''doughnut'',\\n            data: {\\n                labels: [''蛋白质'', ''碳水化合物'', ''脂肪''],\\n                datasets: [{\\n                    data: [17, 23, 8],\\n                    backgroundColor: [\\n                        ''#10b981'',\\n                        ''#34d399'',\\n                        ''#6ee7b7''\\n                    ],\\n                    borderWidth: 1\\n                }]\\n            },\\n            options: {\\n                responsive: true,\\n                plugins: {\\n                    title: {\\n                        display: true,\\n                        text: ''营养摄入比例''\\n                    },\\n                    legend: {\\n                        position: ''bottom''\\n                    }\\n                }\\n            }\\n        });\\n    </script>\\n</body>\\n</html>"}', '2025-11-28 17:37:51', '2025-11-28 17:38:16');
INSERT INTO `custom_reports` (`id`, `user_id`, `report_type`, `title`, `generation_date`, `status`, `report_data`, `created_at`, `updated_at`) VALUES ('baa47d7e-5768-44d7-8954-0f99c665cc08', '0531fee0-45a5-4bba-8d3f-84cd6c31c1bf', 'ai_analysis', 'AI健康数据解读报告', '2025-11-28 18:20:08', 'active', '{"html":"<!DOCTYPE html>\\n<html lang=\\"zh-CN\\">\\n<head>\\n    <meta charset=\\"UTF-8\\">\\n    <meta name=\\"viewport\\" content=\\"width=device-width, initial-scale=1.0\\">\\n    <title>健康解读报告 - 用户亲亲亲</title>\\n    <script src=\\"https://cdn.tailwindcss.com\\"></script>\\n    <script src=\\"https://cdn.jsdelivr.net/npm/chart.js\\"></script>\\n</head>\\n<body class=\\"bg-[#f0f9f4] min-h-screen py-8\\">\\n    <div class=\\"max-w-4xl mx-auto px-4\\">\\n        <!-- 免责声明 -->\\n        <div class=\\"bg-white rounded-lg shadow-sm p-6 mb-6\\">\\n            <p class=\\"text-sm text-gray-600 mb-2\\">本报告仅供参考，不构成医疗建议</p>\\n            <p class=\\"text-sm text-gray-600\\">生成时间：2025年11月28日</p>\\n        </div>\\n\\n        <!-- 执行摘要 -->\\n        <div class=\\"bg-white rounded-lg shadow-sm p-6 mb-6\\">\\n            <h2 class=\\"text-2xl font-bold text-gray-800 mb-4\\">执行摘要</h2>\\n            <p class=\\"text-gray-700\\">用户亲亲亲，45岁男性，身高174cm，当前体重70kg，目标体重65kg。整体健康评分为78分，主要改善领域为运动（评分48分）。已购买21天减肥计划，计划从11月29日开始执行。</p>\\n        </div>\\n\\n        <!-- 数据概览 -->\\n        <div class=\\"bg-white rounded-lg shadow-sm p-6 mb-6\\">\\n            <h2 class=\\"text-2xl font-bold text-gray-800 mb-4\\">数据概览</h2>\\n            \\n            <div class=\\"grid grid-cols-1 md:grid-cols-2 gap-6 mb-6\\">\\n                <div class=\\"bg-gray-50 rounded-lg p-4\\">\\n                    <h3 class=\\"font-semibold text-gray-700 mb-2\\">基本信息</h3>\\n                    <p class=\\"text-gray-600\\">年龄：45岁</p>\\n                    <p class=\\"text-gray-600\\">身高：174cm</p>\\n                    <p class=\\"text-gray-600\\">当前体重：70kg</p>\\n                    <p class=\\"text-gray-600\\">目标体重：65kg</p>\\n                    <p class=\\"text-gray-600\\">基础代谢率：1567.5千卡</p>\\n                </div>\\n                \\n                <div class=\\"bg-gray-50 rounded-lg p-4\\">\\n                    <h3 class=\\"font-semibold text-gray-700 mb-2\\">健康评分</h3>\\n                    <p class=\\"text-gray-600\\">整体评分：78分</p>\\n                    <p class=\\"text-gray-600\\">饮食评分：85分</p>\\n                    <p class=\\"text-gray-600\\">运动评分：48分</p>\\n                    <p class=\\"text-gray-600\\">休息评分：85分</p>\\n                    <p class=\\"text-gray-600\\">心理评分：100分</p>\\n                </div>\\n            </div>\\n\\n            <!-- 图表区域 -->\\n            <div class=\\"grid grid-cols-1 md:grid-cols-2 gap-6\\">\\n                <div class=\\"bg-gray-50 rounded-lg p-4\\">\\n                    <canvas id=\\"weightChart\\"></canvas>\\n                </div>\\n                <div class=\\"bg-gray-50 rounded-lg p-4\\">\\n                    <canvas id=\\"scoreChart\\"></canvas>\\n                </div>\\n                <div class=\\"bg-gray-50 rounded-lg p-4\\">\\n                    <canvas id=\\"goalChart\\"></canvas>\\n                </div>\\n                <div class=\\"bg-gray-50 rounded-lg p-4\\">\\n                    <canvas id=\\"planChart\\"></canvas>\\n                </div>\\n            </div>\\n        </div>\\n\\n        <!-- 健康评估 -->\\n        <div class=\\"bg-white rounded-lg shadow-sm p-6 mb-6\\">\\n            <h2 class=\\"text-2xl font-bold text-gray-800 mb-4\\">健康评估</h2>\\n            <p class=\\"text-gray-700 mb-4\\">您的整体健康状况良好，心理状态优秀（100分），饮食和休息习惯良好（均为85分）。主要需要改善的是运动习惯，当前运动评分为48分，是影响整体健康评分的主要因素。</p>\\n            <p class=\\"text-gray-700\\">您的基础代谢率为1567.5千卡，考虑到久坐的生活方式，建议通过增加日常活动量来提高能量消耗，配合21天减肥计划实现减重目标。</p>\\n        </div>\\n\\n        <!-- 关键发现 -->\\n        <div class=\\"bg-white rounded-lg shadow-sm p-6 mb-6\\">\\n            <h2 class=\\"text-2xl font-bold text-gray-800 mb-4\\">关键发现</h2>\\n            <ul class=\\"list-disc list-inside text-gray-700 space-y-2\\">\\n                <li>运动习惯是当前最需要改善的健康领域</li>\\n                <li>体重管理需要重点关注，目标减重5kg</li>\\n                <li>久坐生活方式需要调整以提升整体健康水平</li>\\n                <li>已制定21天减肥计划，具备良好的执行基础</li>\\n                <li>心理状态优秀，为健康改善提供了良好支持</li>\\n            </ul>\\n        </div>\\n\\n        <!-- 个性化建议 -->\\n        <div class=\\"bg-white rounded-lg shadow-sm p-6 mb-6\\">\\n            <h2 class=\\"text-2xl font-bold text-gray-800 mb-4\\">个性化建议</h2>\\n            \\n            <div class=\\"space-y-6\\">\\n                <div class=\\"border-l-4 border-green-500 pl-4\\">\\n                    <h3 class=\\"font-semibold text-gray-800 mb-2\\">1. 建立日常步行习惯</h3>\\n                    <p class=\\"text-gray-700 mb-1\\"><strong>触发条件：</strong>久坐超过1小时</p>\\n                    <p class=\\"text-gray-700 mb-1\\"><strong>微习惯：</strong>每小时起身走动5分钟</p>\\n                    <p class=\\"text-gray-700 mb-1\\"><strong>进阶路径：</strong>逐步增加到每天步行30分钟</p>\\n                    <p class=\\"text-gray-700\\"><strong>预期收益：</strong>提高基础代谢，改善血液循环</p>\\n                </div>\\n\\n                <div class=\\"border-l-4 border-green-500 pl-4\\">\\n                    <h3 class=\\"font-semibold text-gray-800 mb-2\\">2. 力量训练入门</h3>\\n                    <p class=\\"text-gray-700 mb-1\\"><strong>触发条件：</strong>每周3次，每次15分钟</p>\\n                    <p class=\\"text-gray-700 mb-1\\"><strong>微习惯：</strong>使用自重训练（深蹲、俯卧撑）</p>\\n                    <p class=\\"text-gray-700 mb-1\\"><strong>进阶路径：</strong>逐步增加组数和难度</p>\\n                    <p class=\\"text-gray-700\\"><strong>预期收益：</strong>增加肌肉量，提高基础代谢</p>\\n                </div>\\n\\n                <div class=\\"border-l-4 border-green-500 pl-4\\">\\n                    <h3 class=\\"font-semibold text-gray-800 mb-2\\">3. 饮食结构调整</h3>\\n                    <p class=\\"text-gray-700 mb-1\\"><strong>触发条件：</strong>每日三餐前</p>\\n                    <p class=\\"text-gray-700 mb-1\\"><strong>微习惯：</strong>增加蔬菜摄入，控制主食分量</p>\\n                    <p class=\\"text-gray-700 mb-1\\"><strong>进阶路径：</strong>学习营养搭配，优化蛋白质摄入</p>\\n                    <p class=\\"text-gray-700\\"><strong>预期收益：</strong>控制热量摄入，促进减重</p>\\n                </div>\\n\\n                <div class=\\"border-l-4 border-green-500 pl-4\\">\\n                    <h3 class=\\"font-semibold text-gray-800 mb-2\\">4. 水分摄入管理</h3>\\n                    <p class=\\"text-gray-700 mb-1\\"><strong>触发条件：</strong>起床后、餐前、运动前后</p>\\n                    <p class=\\"text-gray-700 mb-1\\"><strong>微习惯：</strong>每天喝8杯水（约2升）</p>\\n                    <p class=\\"text-gray-700 mb-1\\"><strong>进阶路径：</strong>定时定量饮水，避免口渴</p>\\n                    <p class=\\"text-gray-700\\"><strong>预期收益：</strong>促进新陈代谢，控制食欲</p>\\n                </div>\\n\\n                <div class=\\"border-l-4 border-green-500 pl-4\\">\\n                    <h3 class=\\"font-semibold text-gray-800 mb-2\\">5. 睡眠质量优化</h3>\\n                    <p class=\\"text-gray-700 mb-1\\"><strong>触发条件：</strong>晚上10点前</p>\\n                    <p class=\\"text-gray-700 mb-1\\"><strong>微习惯：</strong>建立固定睡眠时间</p>\\n                    <p class=\\"text-gray-700 mb-1\\"><strong>进阶路径：</strong>优化睡眠环境，减少睡前屏幕时间</p>\\n                    <p class=\\"text-gray-700\\"><strong>预期收益：</strong>提高恢复能力，调节激素平衡</p>\\n                </div>\\n            </div>\\n        </div>\\n\\n        <!-- 行动计划 -->\\n        <div class=\\"bg-white rounded-lg shadow-sm p-6\\">\\n            <h2 class=\\"text-2xl font-bold text-gray-800 mb-4\\">行动计划</h2>\\n            <div class=\\"space-y-4\\">\\n                <div class=\\"flex items-start\\">\\n                    <div class=\\"bg-green-100 text-green-800 rounded-full w-8 h-8 flex items-center justify-center mr-3 flex-shrink-0\\">1</div>\\n                    <div>\\n                        <h3 class=\\"font-semibold text-gray-800\\">第一周：习惯建立</h3>\\n                        <p class=\\"text-gray-700\\">重点建立步行习惯和饮水习惯，每天记录体重变化</p>\\n                    </div>\\n                </div>\\n                \\n                <div class=\\"flex items-start\\">\\n                    <div class=\\"bg-green-100 text-green-800 rounded-full w-8 h-8 flex items-center justify-center mr-3 flex-shrink-0\\">2</div>\\n                    <div>\\n                        <h3 class=\\"font-semibold text-gray-800\\">第二周：运动强化</h3>\\n                        <p class=\\"text-gray-700\\">加入力量训练，优化饮食结构，目标减重1-2kg</p>\\n                    </div>\\n                </div>\\n                \\n                <div class=\\"flex items-start\\">\\n                    <div class=\\"bg-green-100 text-green-800 rounded-full w-8 h-8 flex items-center justify-center mr-3 flex-shrink-0\\">3</div>\\n                    <div>\\n                        <h3 class=\\"font-semibold text-gray-800\\">第三周：巩固成果</h3>\\n                        <p class=\\"text-gray-700\\">全面执行健康计划，评估进展，调整策略</p>\\n                    </div>\\n                </div>\\n            </div>\\n        </div>\\n    </div>\\n\\n    <script>\\n        // 体重图表\\n        const weightCtx = document.getElementById(''weightChart'').getContext(''2d'');\\n        new Chart(weightCtx, {\\n            type: ''bar'',\\n            data: {\\n                labels: [''当前体重'', ''目标体重''],\\n                datasets: [{\\n                    label: ''体重 (kg)'',\\n                    data: [70, 65],\\n                    backgroundColor: [''#4ade80'', ''#22c55e''],\\n                    borderColor: [''#16a34a'', ''#15803d''],\\n                    borderWidth: 1\\n                }]\\n            },\\n            options: {\\n                responsive: true,\\n                plugins: {\\n                    title: {\\n                        display: true,\\n                        text: ''体重目标对比''\\n                    }\\n                },\\n                scales: {\\n                    y: {\\n                        beginAtZero: false,\\n                        min: 60\\n                    }\\n                }\\n            }\\n        });\\n\\n        // 健康评分图表\\n        const scoreCtx = document.getElementById(''scoreChart'').getContext(''2d'');\\n        new Chart(scoreCtx, {\\n            type: ''radar'',\\n            data: {\\n                labels: [''整体'', ''饮食'', ''运动'', ''休息'', ''心理''],\\n                datasets: [{\\n                    label: ''健康评分'',\\n                    data: [78, 85, 48, 85, 100],\\n                    backgroundColor: ''rgba(74, 222, 128, 0.2)'',\\n                    borderColor: ''#22c55e'',\\n                    borderWidth: 2,\\n                    pointBackgroundColor: ''#16a34a''\\n                }]\\n            },\\n            options: {\\n                responsive: true,\\n                scales: {\\n                    r: {\\n                        beginAtZero: true,\\n                        max: 100\\n                    }\\n                },\\n                plugins: {\\n                    title: {\\n                        display: true,\\n                        text: ''健康评分分布''\\n                    }\\n                }\\n            }\\n        });\\n\\n        // 减重目标图表\\n        const goalCtx = document.getElementById(''goalChart'').getContext(''2d'');\\n        new Chart(goalCtx, {\\n            type: ''doughnut'',\\n            data: {\\n                labels: [''已减重量'', ''剩余目标''],\\n                datasets: [{\\n                    data: [0, 5],\\n                    backgroundColor: [''#d1fae5'', ''#bbf7d0''],\\n                    borderColor: [''#86efac'', ''#4ade80''],\\n                    borderWidth: 2\\n                }]\\n            },\\n            options: {\\n                responsive: true,\\n                plugins: {\\n                    title: {\\n                        display: true,\\n                        text: ''减重进度''\\n                    }\\n                }\\n            }\\n        });\\n\\n        // 计划执行图表\\n        const planCtx = document.getElementById(''planChart'').getContext(''2d'');\\n        new Chart(planCtx, {\\n            type: ''line'',\\n            data: {\\n                labels: [''第1周'', ''第2周'', ''第3周''],\\n                datasets: [{\\n                    label: ''预计减重进度 (kg)'',\\n                    data: [1, 2, 2],\\n                    backgroundColor: ''rgba(34, 197, 94, 0.1)'',\\n                    borderColor: ''#16a34a'',\\n                    borderWidth: 2,\\n                    tension: 0.3,\\n                    fill: true\\n                }]\\n            },\\n            options: {\\n                responsive: true,\\n                plugins: {\\n                    title: {\\n                        display: true,\\n                        text: ''21天减重计划预期''\\n                    }\\n                },\\n                scales: {\\n                    y: {\\n                        beginAtZero: true,\\n                        max: 5\\n                    }\\n                }\\n            }\\n        });\\n    </script>\\n</body>\\n</html>"}', '2025-11-28 17:39:36', '2025-11-28 18:20:08');
INSERT INTO `custom_reports` (`id`, `user_id`, `report_type`, `title`, `generation_date`, `status`, `report_data`, `created_at`, `updated_at`) VALUES ('2a029a00-89d9-4d0f-9466-47f968f89e87', 'aa51a5ae-2721-4e23-b843-0758066e2dba', 'ai_analysis', 'AI健康数据解读报告', '2025-12-01 13:50:54', 'active', '{"html":"<!DOCTYPE html>\\n<html lang=\\"zh-CN\\">\\n<head>\\n    <meta charset=\\"UTF-8\\">\\n    <meta name=\\"viewport\\" content=\\"width=device-width, initial-scale=1.0\\">\\n    <title>健康解读报告 - 温柔的小鹿</title>\\n    <script src=\\"https://cdn.tailwindcss.com\\"></script>\\n    <script src=\\"https://cdn.jsdelivr.net/npm/chart.js\\"></script>\\n    <style>\\n        body {\\n            background-color: #f0f9f4;\\n        }\\n    </style>\\n</head>\\n<body class=\\"p-4 md:p-8 font-sans text-gray-800\\">\\n    <div class=\\"max-w-6xl mx-auto\\">\\n        <!-- 免责声明 -->\\n        <div class=\\"mb-8 p-4 bg-white rounded-xl shadow-sm border-l-4 border-amber-400\\">\\n            <p class=\\"text-sm text-gray-600\\"><strong>免责声明：</strong>本报告基于您提供的数据生成，旨在提供健康趋势分析和个性化建议参考，不构成专业的医疗诊断或治疗建议。如有健康问题，请务必咨询医生或专业医疗人员。</p>\\n            <p class=\\"text-sm text-gray-600 mt-2\\"><strong>报告生成时间：</strong>2025年11月30日</p>\\n        </div>\\n\\n        <!-- 报告标题 -->\\n        <header class=\\"mb-10 text-center\\">\\n            <h1 class=\\"text-3xl md:text-4xl font-bold text-green-800 mb-2\\">健康解读报告</h1>\\n            <p class=\\"text-lg text-gray-600\\">用户：温柔的小鹿 | 年龄：35岁 | 目标：提升自信</p>\\n        </header>\\n\\n        <!-- 执行摘要 -->\\n        <section class=\\"mb-10 bg-white p-6 rounded-2xl shadow-sm\\">\\n            <h2 class=\\"text-2xl font-bold text-green-700 mb-4 pb-2 border-b\\">执行摘要</h2>\\n            <p class=\\"text-gray-700 leading-relaxed\\">您好，温柔的小鹿！欢迎查看您的首份健康报告。您已迈出了健康管理的第一步——记录初始体重。当前您的整体健康评分为<strong class=\\"text-green-700\\">77分</strong>，处于良好水平，其中<strong class=\\"text-green-700\\">心理状态（100分）</strong>和<strong class=\\"text-green-700\\">饮食（85分）</strong>表现优异。报告识别出<strong class=\\"text-amber-600\\">“作息”</strong>是您当前最主要的改善领域（休息评分50分）。本报告将结合您的个人目标（减重至65kg，提升自信），为您提供数据洞察和可执行的行动方案。</p>\\n        </section>\\n\\n        <!-- 数据概览与图表 -->\\n        <section class=\\"mb-10\\">\\n            <h2 class=\\"text-2xl font-bold text-green-700 mb-6\\">数据概览</h2>\\n            <div class=\\"grid grid-cols-1 md:grid-cols-2 gap-6\\">\\n                <!-- 图表1：健康评分雷达图 -->\\n                <div class=\\"bg-white p-5 rounded-2xl shadow-sm\\">\\n                    <h3 class=\\"text-xl font-semibold mb-4 text-gray-800\\">健康维度评分</h3>\\n                    <div class=\\"h-64\\">\\n                        <canvas id=\\"assessmentChart\\"></canvas>\\n                    </div>\\n                </div>\\n                <!-- 图表2：体重目标进度 -->\\n                <div class=\\"bg-white p-5 rounded-2xl shadow-sm\\">\\n                    <h3 class=\\"text-xl font-semibold mb-4 text-gray-800\\">体重目标进度</h3>\\n                    <div class=\\"h-64\\">\\n                        <canvas id=\\"weightChart\\"></canvas>\\n                    </div>\\n                </div>\\n                <!-- 图表3：BMI与标准范围 -->\\n                <div class=\\"bg-white p-5 rounded-2xl shadow-sm md:col-span-2\\">\\n                    <h3 class=\\"text-xl font-semibold mb-4 text-gray-800\\">BMI指数分析</h3>\\n                    <div class=\\"h-64\\">\\n                        <canvas id=\\"bmiChart\\"></canvas>\\n                    </div>\\n                </div>\\n            </div>\\n        </section>\\n\\n        <!-- 健康评估 -->\\n        <section class=\\"mb-10 bg-white p-6 rounded-2xl shadow-sm\\">\\n            <h2 class=\\"text-2xl font-bold text-green-700 mb-4 pb-2 border-b\\">健康评估</h2>\\n            <div class=\\"grid grid-cols-2 md:grid-cols-4 gap-4\\">\\n                <div class=\\"text-center p-4 bg-green-50 rounded-xl\\">\\n                    <p class=\\"text-sm text-gray-600\\">整体评分</p>\\n                    <p class=\\"text-3xl font-bold text-green-700\\">77</p>\\n                    <p class=\\"text-xs text-gray-500\\">良好</p>\\n                </div>\\n                <div class=\\"text-center p-4 bg-green-50 rounded-xl\\">\\n                    <p class=\\"text-sm text-gray-600\\">饮食评分</p>\\n                    <p class=\\"text-3xl font-bold text-green-700\\">85</p>\\n                    <p class=\\"text-xs text-gray-500\\">优秀</p>\\n                </div>\\n                <div class=\\"text-center p-4 bg-amber-50 rounded-xl\\">\\n                    <p class=\\"text-sm text-gray-600\\">休息评分</p>\\n                    <p class=\\"text-3xl font-bold text-amber-600\\">50</p>\\n                    <p class=\\"text-xs text-gray-500\\">待改善</p>\\n                </div>\\n                <div class=\\"text-center p-4 bg-green-50 rounded-xl\\">\\n                    <p class=\\"text-sm text-gray-600\\">心理评分</p>\\n                    <p class=\\"text-3xl font-bold text-green-700\\">100</p>\\n                    <p class=\\"text-xs text-gray-500\\">完美</p>\\n                </div>\\n            </div>\\n            <p class=\\"mt-6 text-gray-700\\">您的评估显示了一个非常积极的起点：强大的心理韧性和良好的饮食习惯是您健康旅程的坚实基石。当前的主要机会点在于<strong>作息规律与睡眠质量</strong>的提升，这将对您的精力、运动表现乃至体重管理产生积极影响。</p>\\n        </section>\\n\\n        <!-- 关键发现 -->\\n        <section class=\\"mb-10 bg-white p-6 rounded-2xl shadow-sm\\">\\n            <h2 class=\\"text-2xl font-bold text-green-700 mb-4 pb-2 border-b\\">关键发现</h2>\\n            <ul class=\\"list-disc pl-5 space-y-3 text-gray-700\\">\\n                <li><strong>优势突出：</strong>您的心理状态满分，表明您有极佳的心态和动力去实现健康目标。饮食评分85分，说明您已具备良好的饮食意识或习惯。</li>\\n                <li><strong>核心短板：</strong>“作息”是系统识别出的首要改善领域，休息评分仅为50分。规律作息是健康减重和精力管理的关键。</li>\\n                <li><strong>数据起点：</strong>您已记录初始体重（70kg），这是追踪变化、衡量进展的宝贵基线。根据您的身高（170cm），当前BMI指数为24.2，处于“健康”范围的上限。</li>\\n                <li><strong>目标明确：</strong>您设定了将体重降至65kg（BMI降至22.5）的目标，这是一个健康且可行的目标，有助于提升自信和身体感受。</li>\\n                <li><strong>数据待丰富：</strong>目前仅记录了体重数据。未来增加睡眠、步数、饮水等记录，将使报告更全面，建议更精准。</li>\\n            </ul>\\n        </section>\\n\\n        <!-- 个性化建议 -->\\n        <section class=\\"mb-10\\">\\n            <h2 class=\\"text-2xl font-bold text-green-700 mb-6\\">个性化健康建议</h2>\\n            <div class=\\"space-y-6\\">\\n                <!-- 建议1 -->\\n                <div class=\\"bg-white p-6 rounded-2xl shadow-sm border-l-4 border-green-500\\">\\n                    <h3 class=\\"text-xl font-semibold mb-3 text-gray-800\\">1. 建立规律的睡眠仪式</h3>\\n                    <p class=\\"text-sm text-gray-600 mb-3\\"><strong>触发条件：</strong>晚上10点后，或感到困倦但仍在刷手机时。</strong></p>\\n                    <div class=\\"grid grid-cols-1 md:grid-cols-3 gap-4 text-sm\\">\\n                        <div class=\\"bg-green-50 p-3 rounded-lg\\">\\n                            <p class=\\"font-medium text-green-700 mb-1\\">微习惯</p>\\n                            <p>设定一个固定的“电子产品静默时间”（如睡前30分钟），将手机放在远离床头的地方充电。</p>\\n                        </div>\\n                        <div class=\\"bg-green-50 p-3 rounded-lg\\">\\n                            <p class=\\"font-medium text-green-700 mb-1\\">进阶路径</p>\\n                            <p>静默时间里进行5分钟深呼吸或阅读纸质书。每周记录3次以上实际入睡时间，逐步向目标就寝时间靠拢。</p>\\n                        </div>\\n                        <div class=\\"bg-green-50 p-3 rounded-lg\\">\\n                            <p class=\\"font-medium text-green-700 mb-1\\">预期收益</p>\\n                            <p>提升睡眠质量，增加深度睡眠，白天精力更充沛，有助于控制因疲劳导致的食欲波动。</p>\\n                        </div>\\n                    </div>\\n                </div>\\n                <!-- 建议2 -->\\n                <div class=\\"bg-white p-6 rounded-2xl shadow-sm border-l-4 border-green-500\\">\\n                    <h3 class=\\"text-xl font-semibold mb-3 text-gray-800\\">2. 启动每日体重观察习惯</h3>\\n                    <p class=\\"text-sm text-gray-600 mb-3\\"><strong>触发条件：</strong>每天早晨起床如厕后，穿轻薄衣物时。</strong></p>\\n                    <div class=\\"grid grid-cols-1 md:grid-cols-3 gap-4 text-sm\\">\\n                        <div class=\\"bg-green-50 p-3 rounded-lg\\">\\n                            <p class=\\"font-medium text-green-700 mb-1\\">微习惯</p>\\n                            <p>每周选择2-3个早晨（如周一、周三、周五），在固定时间用同一台秤测量体重并记录在App中。</p>\\n                        </div>\\n                        <div class=\\"bg-green-50 p-3 rounded-lg\\">\\n                            <p class=\\"font-medium text-green-700 mb-1\\">进阶路径</p>\\n                            <p>观察每周趋势而非每日波动。体重稳定或下降时，给自己一个小奖励（如一杯好茶）。</p>\\n                        </div>\\n                        <div class=\\"bg-green-50 p-3 rounded-lg\\">\\n                            <p class=\\"font-medium text-green-700 mb-1\\">预期收益</p>\\n                            <p>建立数据敏感性，客观追踪减重进度，避免因短期波动产生焦虑，用事实增强控制感与自信。</p>\\n                        </div>\\n                    </div>\\n                </div>\\n                <!-- 建议3 -->\\n                <div class=\\"bg-white p-6 rounded-2xl shadow-sm border-l-4 border-green-500\\">\\n                    <h3 class=\\"text-xl font-semibold mb-3 text-gray-800\\">3. 利用“活跃”基础，融入趣味运动</h3>\\n                    <p class=\\"text-sm text-gray-600 mb-3\\"><strong>触发条件：</strong>久坐1小时后，或感觉需要活动身体时。</strong></p>\\n                    <div class=\\"grid grid-cols-1 md:grid-cols-3 gap-4 text-sm\\">\\n                        <div class=\\"bg-green-50 p-3 rounded-lg\\">\\n                            <p class=\\"font-medium text-green-700 mb-1\\">微习惯</p>\\n                            <p>每天午餐后或工作间隙，进行一次10分钟的“运动零食”，如快走、拉伸或跟跳一段欢快的舞蹈视频。</p>\\n                        </div>\\n                        <div class=\\"bg-green-50 p-3 rounded-lg\\">\\n                            <p class=\\"font-medium text-green-700 mb-1\\">进阶路径</p>\\n                            <p>每周安排2次30分钟您真正享受的运动（如瑜伽、骑行、羽毛球），并记录在App的“运动”项目中。</p>\\n                        </div>\\n                        <div class=\\"bg-green-50 p-3 rounded-lg\\">\\n                            <p class=\\"font-medium text-green-700 mb-1\\">预期收益</p>\\n                            <p>提升日常消耗，愉悦心情，巩固“活跃”的生活方式，为创造热量缺口、塑造体型打下基础。</p>\\n                        </div>\\n                    </div>\\n                </div>\\n                <!-- 建议4 -->\\n                <div class=\\"bg-white p-6 rounded-2xl shadow-sm border-l-4 border-green-500\\">\\n                    <h3 class=\\"text-xl font-semibold mb-3 text-gray-800\\">4. 强化优质饮水习惯</h3>\\n                    <p class=\\"text-sm text-gray-600 mb-3\\"><strong>触发条件：</strong>开始工作、餐前、或感觉口干时。</strong></p>\\n                    <div class=\\"grid grid-cols-1 md:grid-cols-3 gap-4 text-sm\\">\\n                        <div class=\\"bg-green-50 p-3 rounded-lg\\">\\n                            <p class=\\"font-medium text-green-700 mb-1\\">微习惯</p>\\n                            <p>在办公桌或常待的地方放置一个好看的水杯，并规定“每次回到座位就先喝几口水”。</p>\\n                        </div>\\n                        <div class=\\"bg-green-50 p-3 rounded-lg\\">\\n                            <p class=\\"font-medium text-green-700 mb-1\\">进阶路径</p>\\n                            <p>尝试在App中记录每日饮水情况，目标设定在1.5-2升。用花草茶、柠檬水增加风味。</p>\\n                        </div>\\n                        <div class=\\"bg-green-50 p-3 rounded-lg\\">\\n                            <p class=\\"font-medium text-green-700 mb-1\\">预期收益</p>\\n                            <p>促进新陈代谢，增加饱腹感，减少误判口渴为饥饿的可能，让皮肤状态更好。</p>\\n                        </div>\\n                    </div>\\n                </div>\\n                <!-- 建议5 -->\\n                <div class=\\"bg-white p-6 rounded-2xl shadow-sm border-l-4 border-green-500\\">\\n                    <h3 class=\\"text-xl font-semibold mb-3 text-gray-800\\">5. 将心理优势转化为行动燃料</h3>\\n                    <p class=\\"text-sm text-gray-600 mb-3\\"><strong>触发条件：</strong>完成一个小健康习惯后，或感到动力十足时。</strong></p>\\n                    <div class=\\"grid grid-cols-1 md:grid-cols-3 gap-4 text-sm\\">\\n                        <div class=\\"bg-green-50 p-3 rounded-lg\\">\\n                            <p class=\\"font-medium text-green-700 mb-1\\">微习惯</p>\\n                            <p>每晚睡前，花1分钟回想今天为健康做的一件好事（如多走了路、喝了足够的水），并肯定自己。</p>\\n                        </div>\\n                        <div class=\\"bg-green-50 p-3 rounded-lg\\">\\n                            <p class=\\"font-medium text-green-700 mb-1\\">进阶路径</p>\\n                            <p>将健康目标与提升“自信”的愿景具体关联。例如：“规律作息让我气色更好，会议中更从容”。</p>\\n                        </div>\\n                        <div class=\\"bg-green-50 p-3 rounded-lg\\">\\n                            <p class=\\"font-medium text-green-700 mb-1\\">预期收益</p>\\n                            <p>强化正向反馈循环，让健康的改变源于自我关爱而非压力，使旅程更可持续、更快乐。</p>\\n                        </div>\\n                    </div>\\n                </div>\\n            </div>\\n        </section>\\n\\n        <!-- 行动计划 -->\\n        <section class=\\"bg-white p-6 rounded-2xl shadow-sm\\">\\n            <h2 class=\\"text-2xl font-bold text-green-700 mb-4 pb-2 border-b\\">接下来2周的行动计划</h2>\\n            <div class=\\"overflow-x-auto\\">\\n                <table class=\\"w-full text-sm text-left text-gray-700\\">\\n                    <thead class=\\"text-xs text-gray-700 uppercase bg-green-50\\">\\n                        <tr>\\n                            <th scope=\\"col\\" class=\\"px-4 py-3\\">周期</th>\\n                            <th scope=\\"col\\" class=\\"px-4 py-3\\">核心行动</th>\\n                            <th scope=\\"col\\" class=\\"px-4 py-3\\">数据记录</th>\\n                            <th scope=\\"col\\" class=\\"px-4 py-3\\">成功标志</th>\\n                        </tr>\\n                    </thead>\\n                    <tbody>\\n                        <tr class=\\"bg-white border-b hover:bg-green-50\\">\\n                            <td class=\\"px-4 py-3 font-medium\\">第1周</td>\\n                            <td class=\\"px-4 py-3\\">1. 执行“睡眠静默时间”至少5晚。<br>2. 完成2次晨间体重记录。<br>3. 每天进行1次10分钟“运动零食”。</td>\\n                            <td class=\\"px-4 py-3\\">在App中记录2次体重。尝试记录1次睡眠感受。</td>\\n                            <td class=\\"px-4 py-3\\">感觉早晨起床更轻松；成功记录初始数据。</td>\\n                        </tr>\\n                        <tr class=\\"bg-white border-b hover:bg-green-50\\">\\n                            <td class=\\"px-4 py-3 font-medium\\">第2周</td>\\n                            <td class=\\"px-4 py-3\\">1. 保持睡眠仪式，尝试一次睡前阅读。<br>2. 完成3次体重记录，观察趋势。<br>3. 安排1次30分钟喜爱的正式运动。</td>\\n                            <td class=\\"px-4 py-3\\">记录3次体重和1次运动。开始记录每日饮水（可选）。</td>\\n                            <td class=\\"px-4 py-3\\">体重曲线平稳或略有下降；从运动中感受到乐趣。</td>\\n                        </tr>\\n                    </tbody>\\n                </table>\\n            </div>\\n            <p class=\\"mt-6 text-gray-700 text-sm\\">请记住，改变在于持续，而非完美。从这些小小的行动开始，您已经走在了通往更健康、更自信自己的道路上。两周后，期待看到您更丰富的数据和进步！</p>\\n        </section>\\n\\n        <footer class=\\"mt-12 pt-6 border-t border-gray-300 text-center text-sm text-gray-500\\">\\n            <p>© 2025 健康数据分析报告 | 为您量身定制</p>\\n        </footer>\\n    </div>\\n\\n    <script>\\n        // 图表1：健康评分雷达图\\n        const ctx1 = document.getElementById(''assessmentChart'').getContext(''2d'');\\n        new Chart(ctx1, {\\n            type: ''radar'',\\n            data: {\\n                labels: [''饮食'', ''运动'', ''休息'', ''心理'', ''健身''],\\n                datasets: [{\\n                    label: ''您的评分'',\\n                    data: [85, 78, 50, 100, 70],\\n                    backgroundColor: ''rgba(72, 187, 120, 0.2)'',\\n                    borderColor: ''#48bb78'',\\n                    borderWidth: 2,\\n                    pointBackgroundColor: ''#48bb78'',\\n                }]\\n            },\\n            options: {\\n                scales: {\\n                    r: {\\n                        beginAtZero: true,\\n                        max: 100,\\n                        ticks: { stepSize: 20 },\\n                        grid: { color: ''rgba(0,0,0,0.1)'' },\\n                        pointLabels: { font: { size: 13 } }\\n                    }\\n                },\\n                plugins: { legend: { display: false } },\\n                maintainAspectRatio: false\\n            }\\n        });\\n\\n        // 图表2：体重目标进度\\n        const ctx2 = document.getElementById(''weightChart'').getContext(''2d'');\\n        new Chart(ctx2, {\\n            type: ''bar'',\\n            data: {\\n                labels: [''当前体重'', ''目标体重''],\\n                datasets: [{\\n                    label: ''体重 (kg)'',\\n                    data: [70, 65],\\n                    backgroundColor: [''#48bb78'', ''#c6f6d5''],\\n                    borderColor: [''#38a169'', ''#9ae6b4''],\\n                    borderWidth: 1\\n                }]\\n            },\\n            options: {\\n                scales: {\\n                    y: {\\n                        beginAtZero: false,\\n                        min: 60,\\n                        max: 75,\\n                        grid: { color: ''rgba(0,0,0,0.05)'' },\\n                        ticks: { callback: function(value) { return value + '' kg''; } }\\n                    }\\n                },\\n                plugins: {\\n                    legend: { display: false },\\n                    tooltip: { callbacks: { label: function(context) { return context.dataset.label + '': '' + context.parsed.y + '' kg''; } } }\\n                },\\n                maintainAspectRatio: false\\n            }\\n        });\\n\\n        // 图表3：BMI与标准范围\\n        const ctx3 = document.getElementById(''bmiChart'').getContext(''2d'');\\n        // 计算BMI\\n        const heightM = 1.70;\\n        const currentBMI = (70 / (heightM * heightM)).toFixed(1);\\n        const targetBMI = (65 / (heightM * heightM)).toFixed(1);\\n\\n        new Chart(ctx3, {\\n            type: ''line'',\\n            data: {\\n                labels: [''偏瘦 (<18.5)'', ''健康 (18.5-24)'', ''超重 (24-28)'', ''肥胖 (>28)''],\\n                datasets: [{\\n                    label: ''标准范围'',\\n                    data: [18.5, 24, 28, null], // 画范围线\\n                    borderColor: ''#e2e8f0'',\\n                    borderWidth: 2,\\n                    borderDash: [5, 5],\\n                    fill: false,\\n                    pointRadius: 0\\n                },\\n                {\\n                    label: ''您的轨迹'',\\n                    data: [null, currentBMI, targetBMI, null],\\n                    backgroundColor: ''rgba(72, 187, 120, 0.1)'',\\n                    borderColor: ''#48bb78'',\\n                    borderWidth: 3,\\n                    tension: 0.3,\\n                    pointBackgroundColor: ''#48bb78'',\\n                    pointRadius: 6\\n                }]\\n            },\\n            options: {\\n                scales: {\\n                    y: {\\n                        beginAtZero: false,\\n                        min: 16,\\n                        max: 30,\\n                        grid: { color: ''rgba(0,0,0,0.05)'' },\\n                        ticks: { callback: function(value) { return ''BMI '' + value; } }\\n                    }\\n                },\\n                plugins: {\\n                    tooltip: {\\n                        callbacks: {\\n                            label: function(context) {\\n                                if (context.datasetIndex === 1) {\\n                                    if (context.dataIndex === 1) return ''当前 BMI: '' + currentBMI;\\n                                    if (context.dataIndex === 2) return ''目标 BMI: '' + targetBMI;\\n                                }\\n                                return null;\\n                            }\\n                        }\\n                    }\\n                },\\n                maintainAspectRatio: false\\n            }\\n        });\\n    </script>\\n</body>\\n</html>"}', '2025-12-01 13:50:50', '2025-12-01 13:50:54');
INSERT INTO `custom_reports` (`id`, `user_id`, `report_type`, `title`, `generation_date`, `status`, `report_data`, `created_at`, `updated_at`) VALUES ('82139eb9-23f1-443d-97d5-138e3ab6a6a9', '81784f3d-b7c4-4974-ad6c-094856755814', 'ai_analysis', 'AI健康数据解读报告', '2025-12-01 14:28:38', 'active', '{"html":"<!DOCTYPE html>\\n<html lang=\\"zh-CN\\">\\n<head>\\n    <meta charset=\\"UTF-8\\">\\n    <meta name=\\"viewport\\" content=\\"width=device-width, initial-scale=1.0\\">\\n    <title>健康解读报告</title>\\n    <script src=\\"https://cdn.tailwindcss.com\\"></script>\\n    <script src=\\"https://cdn.jsdelivr.net/npm/chart.js\\"></script>\\n    <style>\\n        body {\\n            background-color: #f0f9f4;\\n        }\\n    </style>\\n</head>\\n<body class=\\"p-4 md:p-8 font-sans text-gray-800\\">\\n    <div class=\\"max-w-6xl mx-auto\\">\\n        <!-- 免责声明 -->\\n        <div class=\\"mb-8 p-4 bg-white rounded-xl shadow-sm border border-gray-200\\">\\n            <p class=\\"text-sm text-gray-600 italic\\">本报告仅供参考，不构成医疗建议。生成时间：2025年11月28日</p>\\n        </div>\\n\\n        <!-- 报告标题 -->\\n        <div class=\\"mb-10 text-center\\">\\n            <h1 class=\\"text-3xl md:text-4xl font-bold text-gray-800 mb-2\\">个人健康解读报告</h1>\\n            <p class=\\"text-lg text-gray-600\\">用户，欢迎查看您的健康数据分析报告</p>\\n        </div>\\n\\n        <!-- 执行摘要 -->\\n        <div class=\\"mb-10 p-6 bg-white rounded-xl shadow-sm border border-gray-200\\">\\n            <h2 class=\\"text-2xl font-bold mb-4 text-gray-800 border-b pb-2\\">执行摘要</h2>\\n            <p class=\\"mb-3\\">您好！根据您提供的初始数据，您的整体健康评分为<strong>73分</strong>，处于中等偏上水平。当前的主要改善领域是<strong>体质</strong>，这与您的减重目标高度相关。</p>\\n            <p class=\\"mb-3\\">您的身体质量指数（BMI）约为<strong>29.8</strong>，属于超重范围。从当前体重（82.2公斤）到目标体重（65公斤），您需要减重约17.2公斤。这是一个明确且可实现的长期目标。</p>\\n            <p>目前您的健康数据记录刚刚开始，主要集中在体重上。为了获得更全面的洞察，建议您后续补充记录血糖、睡眠、步数等更多维度的数据。</p>\\n        </div>\\n\\n        <!-- 数据概览与图表 -->\\n        <div class=\\"mb-10 p-6 bg-white rounded-xl shadow-sm border border-gray-200\\">\\n            <h2 class=\\"text-2xl font-bold mb-6 text-gray-800 border-b pb-2\\">数据概览</h2>\\n            <div class=\\"grid grid-cols-1 md:grid-cols-2 gap-6 mb-8\\">\\n                <div class=\\"space-y-4\\">\\n                    <div class=\\"p-4 bg-gray-50 rounded-lg\\">\\n                        <p class=\\"text-gray-600\\">个人信息</p>\\n                        <p class=\\"text-lg font-semibold\\">32岁，女性，身高166cm</p>\\n                    </div>\\n                    <div class=\\"p-4 bg-gray-50 rounded-lg\\">\\n                        <p class=\\"text-gray-600\\">当前与目标体重</p>\\n                        <p class=\\"text-lg font-semibold\\">82.2 kg → 65.0 kg</p>\\n                    </div>\\n                    <div class=\\"p-4 bg-gray-50 rounded-lg\\">\\n                        <p class=\\"text-gray-600\\">活动水平</p>\\n                        <p class=\\"text-lg font-semibold\\">轻度活动</p>\\n                    </div>\\n                    <div class=\\"p-4 bg-gray-50 rounded-lg\\">\\n                        <p class=\\"text-gray-600\\">基础代谢率 (BMR)</p>\\n                        <p class=\\"text-lg font-semibold\\">1538.5 千卡/天</p>\\n                    </div>\\n                </div>\\n                <div class=\\"p-4 bg-gray-50 rounded-lg\\">\\n                    <h3 class=\\"font-bold mb-4 text-gray-800\\">健康评分概览</h3>\\n                    <canvas id=\\"scoreChart\\"></canvas>\\n                </div>\\n            </div>\\n            <div class=\\"grid grid-cols-1 md:grid-cols-2 gap-6\\">\\n                <div class=\\"p-4 bg-gray-50 rounded-lg\\">\\n                    <h3 class=\\"font-bold mb-4 text-gray-800\\">体重目标分解</h3>\\n                    <canvas id=\\"weightChart\\"></canvas>\\n                </div>\\n                <div class=\\"p-4 bg-gray-50 rounded-lg\\">\\n                    <h3 class=\\"font-bold mb-4 text-gray-800\\">数据记录分布</h3>\\n                    <canvas id=\\"dataChart\\"></canvas>\\n                </div>\\n            </div>\\n        </div>\\n\\n        <!-- 健康评估 -->\\n        <div class=\\"mb-10 p-6 bg-white rounded-xl shadow-sm border border-gray-200\\">\\n            <h2 class=\\"text-2xl font-bold mb-4 text-gray-800 border-b pb-2\\">健康评估</h2>\\n            <div class=\\"mb-4\\">\\n                <div class=\\"flex justify-between items-center mb-1\\">\\n                    <span class=\\"font-medium\\">整体健康评分</span>\\n                    <span class=\\"font-bold text-lg\\">73 / 100</span>\\n                </div>\\n                <div class=\\"w-full bg-gray-200 rounded-full h-4\\">\\n                    <div class=\\"bg-green-600 h-4 rounded-full\\" style=\\"width: 73%\\"></div>\\n                </div>\\n            </div>\\n            <div class=\\"grid grid-cols-2 md:grid-cols-3 gap-4 mt-6\\">\\n                <div class=\\"p-4 bg-green-50 rounded-lg\\">\\n                    <p class=\\"text-gray-600 text-sm\\">饮食评分</p>\\n                    <p class=\\"text-2xl font-bold text-green-700\\">100</p>\\n                </div>\\n                <div class=\\"p-4 bg-yellow-50 rounded-lg\\">\\n                    <p class=\\"text-gray-600 text-sm\\">运动评分</p>\\n                    <p class=\\"text-2xl font-bold text-yellow-600\\">66</p>\\n                </div>\\n                <div class=\\"p-4 bg-red-50 rounded-lg\\">\\n                    <p class=\\"text-gray-600 text-sm\\">体能评分</p>\\n                    <p class=\\"text-2xl font-bold text-red-600\\">45</p>\\n                </div>\\n                <div class=\\"p-4 bg-yellow-50 rounded-lg\\">\\n                    <p class=\\"text-gray-600 text-sm\\">休息评分</p>\\n                    <p class=\\"text-2xl font-bold text-yellow-600\\">55</p>\\n                </div>\\n                <div class=\\"p-4 bg-green-50 rounded-lg\\">\\n                    <p class=\\"text-gray-600 text-sm\\">心理评分</p>\\n                    <p class=\\"text-2xl font-bold text-green-700\\">100</p>\\n                </div>\\n                <div class=\\"p-4 bg-gray-100 rounded-lg\\">\\n                    <p class=\\"text-gray-600 text-sm\\">主要改善领域</p>\\n                    <p class=\\"text-lg font-bold text-gray-800\\">体质</p>\\n                </div>\\n            </div>\\n        </div>\\n\\n        <!-- 关键发现 -->\\n        <div class=\\"mb-10 p-6 bg-white rounded-xl shadow-sm border border-gray-200\\">\\n            <h2 class=\\"text-2xl font-bold mb-4 text-gray-800 border-b pb-2\\">关键发现</h2>\\n            <ul class=\\"list-disc pl-5 space-y-3\\">\\n                <li><strong>优势明确：</strong>您的饮食和心理状态评分均为满分，这表明您拥有良好的饮食意识和积极稳定的心态，这是成功减重的重要基础。</li>\\n                <li><strong>核心挑战：</strong>体能评分（45分）和休息评分（55分）是当前的短板，与“轻度活动”水平相符。提升日常活动量和改善睡眠是启动减重进程的关键。</li>\\n                <li><strong>数据起点：</strong>目前仅记录了初始体重，缺乏血糖、睡眠、步数等动态数据。建立持续的数据记录习惯，将帮助您更精准地追踪进展和调整计划。</li>\\n                <li><strong>热量平衡：</strong>基于您的基础代谢率（1538.5千卡/天）和轻度活动水平，每日总热量消耗（TDEE）估计在1850千卡左右。创造约500千卡的每日热量缺口，可实现每周减重约0.5公斤的安全目标。</li>\\n            </ul>\\n        </div>\\n\\n        <!-- 个性化建议 -->\\n        <div class=\\"mb-10 p-6 bg-white rounded-xl shadow-sm border border-gray-200\\">\\n            <h2 class=\\"text-2xl font-bold mb-6 text-gray-800 border-b pb-2\\">个性化建议</h2>\\n            <div class=\\"space-y-6\\">\\n                <!-- 建议1 -->\\n                <div class=\\"p-5 bg-green-50 rounded-xl border border-green-100\\">\\n                    <h3 class=\\"font-bold text-lg mb-3 text-gray-800\\">1. 建立每日步数基础</h3>\\n                    <p><strong>触发条件：</strong>日常以久坐为主，活动量不足。</p>\\n                    <p><strong>微习惯：</strong>每天午餐后或晚饭后，进行15分钟的散步。</p>\\n                    <p><strong>进阶路径：</strong>从每日3000步开始，每周增加500步，逐步达到每日8000-10000步的目标。</p>\\n                    <p><strong>预期收益：</strong>提升日常热量消耗，改善血液循环，为增加运动强度打下基础。</p>\\n                </div>\\n                <!-- 建议2 -->\\n                <div class=\\"p-5 bg-green-50 rounded-xl border border-green-100\\">\\n                    <h3 class=\\"font-bold text-lg mb-3 text-gray-800\\">2. 优化晚餐时间与结构</h3>\\n                    <p><strong>触发条件：</strong>晚餐过晚或过于丰盛，影响睡眠和次日晨重。</p>\\n                    <p><strong>微习惯：</strong>将晚餐时间提前至睡前至少3小时，并保证晚餐包含足量蔬菜和优质蛋白。</p>\\n                    <p><strong>进阶路径：</strong>尝试将全天大部分碳水化合物分配在早餐和午餐，晚餐以蛋白质和蔬菜为主。</p>\\n                    <p><strong>预期收益：</strong>改善夜间消化与睡眠质量，有助于早晨空腹体重稳步下降。</p>\\n                </div>\\n                <!-- 建议3 -->\\n                <div class=\\"p-5 bg-green-50 rounded-xl border border-green-100\\">\\n                    <h3 class=\\"font-bold text-lg mb-3 text-gray-800\\">3. 引入每周两次力量训练</h3>\\n                    <p><strong>触发条件：</strong>体能评分较低，肌肉量可能不足，影响基础代谢。</p>\\n                    <p><strong>微习惯：</strong>每周安排两次，每次20分钟，在家进行自重训练（如深蹲、弓步、跪姿俯卧撑）。</p>\\n                    <p><strong>进阶路径：</strong>逐步增加组数或加入弹力带、小哑铃增加阻力，最终形成每周3次的力量训练习惯。</p>\\n                    <p><strong>预期收益：</strong>增加肌肉量，提升基础代谢率，让减脂更高效，体型更紧致。</p>\\n                </div>\\n                <!-- 建议4 -->\\n                <div class=\\"p-5 bg-green-50 rounded-xl border border-green-100\\">\\n                    <h3 class=\\"font-bold text-lg mb-3 text-gray-800\\">4. 设定规律的睡眠时间</h3>\\n                    <p><strong>触发条件：</strong>休息评分有待提高，睡眠不规律影响激素平衡和恢复。</p>\\n                    <p><strong>微习惯：</strong>固定每天上床和起床的时间，即使周末也尽量保持一致，前后波动不超过1小时。</p>\\n                    <p><strong>进阶路径：</strong>睡前一小时关闭电子设备，营造黑暗、安静的睡眠环境，可尝试阅读或冥想助眠。</p>\\n                    <p><strong>预期收益：</strong>稳定皮质醇和瘦素水平，减少夜间饥饿感，提升白天的精力和运动表现。</p>\\n                </div>\\n                <!-- 建议5 -->\\n                <div class=\\"p-5 bg-green-50 rounded-xl border border-green-100\\">\\n                    <h3 class=\\"font-bold text-lg mb-3 text-gray-800\\">5. 启动每周体重记录</h3>\\n                    <p><strong>触发条件：</strong>目前只有单次体重数据，无法观察趋势。</p>\\n                    <p><strong>微习惯：</strong>每周固定一天（如周一早晨），在空腹、排便后穿着相似衣物测量体重并记录。</p>\\n                    <p><strong>进阶路径：</strong>在记录体重的同时，可以每周测量一次腰围，并开始尝试记录每日饮水量和大致步数。</p>\\n                    <p><strong>预期收益：</strong>通过数据可视化追踪长期趋势，避免因短期波动而焦虑，让进步看得见。</p>\\n                </div>\\n            </div>\\n        </div>\\n\\n        <!-- 行动计划 -->\\n        <div class=\\"p-6 bg-white rounded-xl shadow-sm border border-gray-200\\">\\n            <h2 class=\\"text-2xl font-bold mb-4 text-gray-800 border-b pb-2\\">两周启动行动计划</h2>\\n            <div class=\\"overflow-x-auto\\">\\n                <table class=\\"w-full text-left border-collapse\\">\\n                    <thead class=\\"bg-gray-100\\">\\n                        <tr>\\n                            <th class=\\"p-3 border border-gray-300\\">周期</th>\\n                            <th class=\\"p-3 border border-gray-300\\">核心行动</th>\\n                            <th class=\\"p-3 border border-gray-300\\">数据记录</th>\\n                            <th class=\\"p-3 border border-gray-300\\">目标</th>\\n                        </tr>\\n                    </thead>\\n                    <tbody>\\n                        <tr>\\n                            <td class=\\"p-3 border border-gray-300 font-medium\\">第1周</td>\\n                            <td class=\\"p-3 border border-gray-300\\">1. 每日饭后散步15分钟<br>2. 晚餐提前至8点前完成</td>\\n                            <td class=\\"p-3 border border-gray-300\\">1. 记录每日是否完成散步<br>2. 记录晚餐时间</td>\\n                            <td class=\\"p-3 border border-gray-300\\">建立两个微习惯，周末测量一次体重。</td>\\n                        </tr>\\n                        <tr class=\\"bg-gray-50\\">\\n                            <td class=\\"p-3 border border-gray-300 font-medium\\">第2周</td>\\n                            <td class=\\"p-3 border border-gray-300\\">1. 保持散步，尝试一次20分钟<br>2. 加入一次家庭力量训练（如深蹲）<br>3. 固定上床时间</td>\\n                            <td class=\\"p-3 border border-gray-300\\">1. 记录散步时长<br>2. 记录力量训练情况<br>3. 记录上床时间</td>\\n                            <td class=\\"p-3 border border-gray-300\\">巩固习惯，感受精力变化，完成第二次体重测量。</td>\\n                        </tr>\\n                    </tbody>\\n                </table>\\n            </div>\\n            <div class=\\"mt-6 p-4 bg-blue-50 rounded-lg border border-blue-100\\">\\n                <p class=\\"font-bold text-blue-800 mb-2\\">💡 温馨提示：</p>\\n                <p class=\\"text-gray-700\\">健康改变是一场马拉松，而非冲刺。请专注于习惯的建立和身体的积极感受，而非仅仅关注体重数字。您的饮食和心理优势是成功的强大保障。祝您旅程愉快！</p>\\n            </div>\\n        </div>\\n    </div>\\n\\n    <script>\\n        // 健康评分雷达图\\n        const scoreCtx = document.getElementById(''scoreChart'').getContext(''2d'');\\n        new Chart(scoreCtx, {\\n            type: ''radar'',\\n            data: {\\n                labels: [''饮食'', ''运动'', ''体能'', ''休息'', ''心理''],\\n                datasets: [{\\n                    label: ''健康维度评分'',\\n                    data: [100, 66, 45, 55, 100],\\n                    backgroundColor: ''rgba(34, 197, 94, 0.2)'',\\n                    borderColor: ''rgb(34, 197, 94)'',\\n                    pointBackgroundColor: ''rgb(34, 197, 94)'',\\n                    pointBorderColor: ''#fff'',\\n                    pointHoverBackgroundColor: ''#fff'',\\n                    pointHoverBorderColor: ''rgb(34, 197, 94)''\\n                }]\\n            },\\n            options: {\\n                scales: {\\n                    r: {\\n                        beginAtZero: true,\\n                        max: 100,\\n                        ticks: { stepSize: 20 },\\n                        pointLabels: { font: { size: 13 } }\\n                    }\\n                },\\n                plugins: { legend: { display: false } },\\n                maintainAspectRatio: false\\n            }\\n        });\\n\\n        // 体重目标进度图\\n        const weightCtx = document.getElementById(''weightChart'').getContext(''2d'');\\n        new Chart(weightCtx, {\\n            type: ''bar'',\\n            data: {\\n                labels: [''当前体重'', ''目标体重'', ''需减重量''],\\n                datasets: [{\\n                    label: ''体重 (kg)'',\\n                    data: [82.2, 65.0, 17.2],\\n                    backgroundColor: [''#ef4444'', ''#22c55e'', ''#f59e0b''],\\n                    borderColor: [''#dc2626'', ''#16a34a'', ''#d97706''],\\n                    borderWidth: 1\\n                }]\\n            },\\n            options: {\\n                scales: {\\n                    y: {\\n                        beginAtZero: true,\\n                        title: { display: true, text: ''体重 (公斤)'' }\\n                    }\\n                },\\n                plugins: { legend: { display: false } },\\n                maintainAspectRatio: false\\n            }\\n        });\\n\\n        // 数据记录分布图\\n        const dataCtx = document.getElementById(''dataChart'').getContext(''2d'');\\n        new Chart(dataCtx, {\\n            type: ''doughnut'',\\n            data: {\\n                labels: [''体重记录'', ''其他数据（待补充）''],\\n                datasets: [{\\n                    data: [1, 5], // 象征性数据，1项体重 vs 其他多项待补充\\n                    backgroundColor: [''#22c55e'', ''#d1d5db''],\\n                    borderWidth: 1,\\n                    borderColor: ''#fff''\\n                }]\\n            },\\n            options: {\\n                plugins: {\\n                    legend: { position: ''bottom'' },\\n                    tooltip: {\\n                        callbacks: {\\n                            label: function(context) {\\n                                let label = context.label || '''';\\n                                if (label) label += '': '';\\n                                if (context.dataIndex === 0) label += ''已开始记录'';\\n                                else label += ''建议后续补充'';\\n                                return label;\\n                            }\\n                        }\\n                    }\\n                },\\n                cutout: ''65%'',\\n                maintainAspectRatio: false\\n            }\\n        });\\n    </script>\\n</body>\\n</html>"}', '2025-12-01 14:26:30', '2025-12-01 14:28:38');
